// DOWNTOWN: the town grid continues east of Station St (x 610 -> 970). 7 blocks of mid / high
// rise towers (6-18 storeys, window grids that glow at night) along Terrace Pde, City Plaza
// with a fountain + food truck, rooftop billboards, neon shop signs (lit at dusk), bus
// shelters, a small car park of stealable cars and the Terrace Tower landmark.
// Streets, lanes, kerbs, footpaths, street trees / lights are generated by the town modules
// from the extended grid (townPlan.js T.X); this file only adds the buildings and furniture.
import * as THREE from 'three';
import { frame, makeChunk, createSignAtlas } from '../town/townKit.js';
import { T } from '../town/townPlan.js';
import { staticCar } from '../town/townBuildings.js';
import { box, cylinder, paint } from '../utils/geom.js';

export const DOWNTOWN = { iFrom: 3, x0: 610, x1: 970, plaza: { i: 4, j: 1 }, carpark: { i: 6, j: 1 } };
const WALLS = ['#b9c0c6', '#cfc6b6', '#9fa9b0', '#d8d2c6', '#a8a196', '#c4cbc4', '#8f979e'];
const GLASS = ['#3f5a6e', '#4a6478', '#36505f', '#58707e'];
const NEON = [['TERRACE COLA', '#1a1a1e', '#ff4f6a'], ['NOODLE BAR', '#1a1a1e', '#4fe0ff'], ['DINER 24H', '#1a1a1e', '#ffd84f'], ['COCKTAILS', '#1a1a1e', '#ff6ad8'], ['CINEMA', '#1a1a1e', '#8aff6a'], ['PIZZA', '#1a1a1e', '#ff8a3a']];
const ADS = [['SURF FM 101.7', '#2f6fc0', '#ffffff'], ['BIG BANK - LOANS', '#1f6a4a', '#f4f1e8'], ['TERRACE COLA', '#c8322a', '#ffffff'], ['FLY QANTARA', '#e2c25a', '#1f1f22'], ['GRAND HOTEL', '#26282c', '#e2c25a']];

/**
 * Office tower: solid core (collider), a glass band on every floor and vertical mullions
 * (a procedural window grid for a handful of boxes), ground-floor lobby + parapet.
 */
export function tower(ch, F, { w, d, floors, floorH = 3.3, wall, glass, lobby = true }) {
  const H = floors * floorH;
  ch.block(F, w, H, d, 0, 0, -d / 2, wall);
  for (let f = 1; f < floors; f++) {
    const y = f * floorH + 0.55, h = floorH - 1.0;
    ch.box(F, w + 0.1, h, 0.1, 0, y, 0.03, glass, { glassy: true });
    ch.box(F, w + 0.1, h, 0.1, 0, y, -d - 0.03, glass, { glassy: true });
    ch.box(F, 0.1, h, d + 0.1, w / 2 + 0.03, y, -d / 2, glass, { glassy: true });
    ch.box(F, 0.1, h, d + 0.1, -w / 2 - 0.03, y, -d / 2, glass, { glassy: true });
  }
  // Mullions (front/back every ~3.2 m, sides too).
  const nW = Math.max(2, Math.round(w / 3.2)), nD = Math.max(2, Math.round(d / 3.2));
  for (let k = 0; k <= nW; k++) {
    const x = -w / 2 + (k * w) / nW;
    ch.box(F, 0.28, H - floorH, 0.22, x, floorH, 0.08, wall);
    ch.box(F, 0.28, H - floorH, 0.22, x, floorH, -d - 0.08, wall);
  }
  for (let k = 1; k < nD; k++) {
    const z = -(k * d) / nD;
    ch.box(F, 0.22, H - floorH, 0.28, w / 2 + 0.08, floorH, z, wall);
    ch.box(F, 0.22, H - floorH, 0.28, -w / 2 - 0.08, floorH, z, wall);
  }
  ch.box(F, w + 0.5, 0.7, d + 0.5, 0, H, -d / 2, '#e6e2da');                // parapet
  ch.box(F, Math.min(8, w / 3), 2.2, Math.min(6, d / 3), w / 6, H + 0.7, -d * 0.55, '#9b9890'); // plant room
  if (lobby) {
    ch.box(F, w * 0.6, 2.8, 0.12, 0, 0.1, 0.06, '#33434e', { glassy: true });
    ch.box(F, w * 0.7, 0.25, 2.4, 0, 3.0, 1.2, '#2b2b2e');                  // canopy
  }
  return H;
}

/** Fountain at (x, z): basin ring, inner pool, three tiers + water columns. */
function fountain(ch, F, lx, lz) {
  const p = F.toW(lx, lz), y = F.y;
  ch.solid.push(cylinder(7.2, 7.4, 0.6, 24, p.x, y, p.z, '#cfc8bb'));
  ch.solid.push(cylinder(6.6, 6.6, 0.5, 24, p.x, y + 0.12, p.z, '#5fa3c4'));
  ch.solid.push(cylinder(1.4, 1.8, 1.6, 12, p.x, y + 0.3, p.z, '#d8d2c6'));
  ch.solid.push(cylinder(3.0, 2.6, 0.35, 16, p.x, y + 1.9, p.z, '#cfc8bb'));
  ch.solid.push(cylinder(2.6, 2.6, 0.2, 16, p.x, y + 2.05, p.z, '#6fb4d4'));
  ch.solid.push(cylinder(0.5, 0.7, 1.4, 8, p.x, y + 2.25, p.z, '#d8d2c6'));
  ch.solid.push(cylinder(0.12, 0.35, 1.6, 6, p.x, y + 3.6, p.z, '#bfe6f6'));  // spout
  ch.colliders.push({ x: p.x, y: y + 0.4, z: p.z, hx: 7.2, hy: 0.4, hz: 7.2, rot: 0 });
}

export function buildDowntown({ parent, plan, rng, atlas: townAtlas }) {
  const out = { chunks: [], colliders: [], places: [], npcSpots: [], updaters: [], stops: [], propChunks: [], landmarks: [], benches: [], towers: 0 };
  const { X, Z, front } = T, y = T.h;
  const neon = createSignAtlas();
  neon.mat.emissiveIntensity = 0.25;
  const chunks = new Map();
  const chunk = (name) => { if (!chunks.has(name)) chunks.set(name, makeChunk(name)); return chunks.get(name); };
  const P = DOWNTOWN.plaza, CP = DOWNTOWN.carpark;
  let tallest = null, k = 0;

  for (let i = DOWNTOWN.iFrom; i < X.length - 1; i++) {
    for (let j = 0; j < Z.length - 1; j++) {
      const ch = chunk(`d${i}${j}`);
      const bx0 = X[i] + front, bx1 = X[i + 1] - front, bz0 = Z[j] + front, bz1 = Z[j + 1] - front;
      const cx = (bx0 + bx1) / 2, bw = bx1 - bx0, bd = bz1 - bz0;
      const pdeSide = j === 0 ? 1 : -1;       // Terrace Pde is the south edge of row 0, north edge of row 1
      if (i === P.i && j === P.j) continue;   // City Plaza (below)
      if (i === CP.i && j === CP.j) {
        // Pde-facing tower + an open car park behind it (stealable cars).
        tower(ch, frame(cx, Z[1] + front, 0, -1, y), { w: bw * 0.86, d: 34, floors: 7, wall: WALLS[k % WALLS.length], glass: GLASS[k % 4] }); k++; out.towers++;
        const lot = frame(cx, bz1, 0, 1, y);
        ch.box(lot, bw - 2, 0.05, 50, 0, 0.04, -26, '#5c5d60');
        for (let x = -bw / 2 + 4; x <= bw / 2 - 4; x += 3.2) ch.box(lot, 0.12, 0.02, 5.2, x, 0.09, -8, '#e8e4d8');
        for (let n = 0; n < 8; n++) {
          const x = -bw / 2 + 5.6 + n * 3.2 * 2.2;
          if (x > bw / 2 - 4) break;
          const p = lot.toW(x, -8);
          staticCar(ch, p.x, p.z, Math.PI, ['sedan', 'hatch', 'suv', 'ute'][n % 4], ['#8a4f3a', '#46566b', '#d8d2c4', '#2f4f6b', '#9aa37a', '#5c5f66'][n % 6]);
        }
        townAtlas.sign(frame(cx - bw / 2 + 6, bz1 + 0.5, 0, 1, y), townAtlas.row('P  CITY PARKING', '#2f6fc0', '#ffffff'), 6, 0.9, 0, 3.0, 0, { u0: 0.1, u1: 0.9 });
        out.places.push({ kind: 'shop', x: cx, z: bz1 - 26, label: 'City Parking' });
        continue;
      }
      // Main tower on Terrace Pde + a second building on the outer street.
      const floors = i === 5 && j === 0 ? 18 : 8 + Math.floor(rng.next() * 9);
      const zPde = j === 0 ? Z[1] - front : Z[1] + front;
      const F1 = frame(cx, zPde, 0, pdeSide, y);
      const d1 = Math.min(40, bd * 0.42), w1 = bw * 0.9;
      const H1 = tower(ch, F1, { w: w1, d: d1, floors, wall: WALLS[k % WALLS.length], glass: GLASS[k % 4] }); k++; out.towers++;
      if (!tallest || H1 > tallest.H) tallest = { H: H1, F: F1, w: w1, d: d1, ch };
      // Neon sign over the lobby (lit at dusk).
      const n = NEON[k % NEON.length];
      neon.sign(F1, neon.row(n[0], n[1], n[2], 'bold 44px Arial'), Math.min(12, w1 * 0.4), 1.0, -w1 * 0.3, 3.7, 0.25);
      const zOut = j === 0 ? Z[0] + front : Z[2] - front;
      const F2 = frame(cx, zOut, 0, -pdeSide, y);
      const fl2 = 5 + Math.floor(rng.next() * 6);
      const H2 = tower(ch, F2, { w: bw * 0.8, d: Math.min(34, bd * 0.36), floors: fl2, wall: WALLS[(k + 3) % WALLS.length], glass: GLASS[(k + 1) % 4] }); out.towers++;
      // Rooftop billboard on every other second building, facing the outer street.
      if ((i + j) % 2 === 0) {
        const ad = ADS[(i + j) % ADS.length];
        const B = frame(cx, zOut, 0, -pdeSide, y);
        ch.box(B, 0.3, 4.0, 0.3, -6, H2 + 0.7, -4, '#2b2b2e'); ch.box(B, 0.3, 4.0, 0.3, 6, H2 + 0.7, -4, '#2b2b2e');
        ch.box(B, 15, 4.6, 0.3, 0, H2 + 3.2, -4.2, '#2b2b2e');
        townAtlas.sign(B, townAtlas.row(ad[0], ad[1], ad[2]), 14.4, 4.0, 0, H2 + 5.5, -4.0);
      }
    }
  }

  // ---- Terrace Tower (landmark): crown + spire on the tallest tower --------------------------
  if (tallest) {
    const { F, H, w, d, ch } = tallest;
    ch.block(F, w * 0.7, 6, d * 0.7, 0, H + 0.7, -d / 2, '#d8d2c6');
    ch.box(F, w * 0.5, 4, d * 0.5, 0, H + 6.7, -d / 2, '#e6e2da');
    ch.solid.push(paint(new THREE.ConeGeometry(1.2, 22, 8).translate(...(() => { const p = F.toW(0, -d / 2); return [p.x, y + H + 10.7 + 11, p.z]; })()), '#cfd3d6', 0.03));
    townAtlas.sign(F, townAtlas.row('TERRACE TOWER', '#26282c', '#e2c25a'), Math.min(20, w * 0.6), 1.6, 0, H - 2.2, 0.2);
    const p = F.toW(0, -d / 2);
    out.landmarks.push({ name: 'Terrace Tower', x: p.x, z: p.z, h: H + 33 });
    out.places.push({ kind: 'landmark', x: p.x, z: p.z, label: 'Terrace Tower' });
  }

  // ---- City Plaza: paving, fountain, trees in planters, benches, food truck, billboards --------
  {
    const ch = chunk(`d${P.i}${P.j}`);
    const bx0 = X[P.i] + T.hw + T.kerb, bx1 = X[P.i + 1] - T.hw - T.kerb, bz0 = Z[P.j] + T.hw + T.kerb, bz1 = Z[P.j + 1] - T.hw - T.kerb;
    const cx = (bx0 + bx1) / 2, cz = (bz0 + bz1) / 2;
    const F = frame(cx, cz, 0, -1, y);
    ch.box(F, bx1 - bx0, 0.06, bz1 - bz0, 0, 0.0, 0, '#d4cbbb');
    for (let r = 0; r < 6; r++) ch.box(F, bx1 - bx0 - 2, 0.02, 0.18, 0, 0.065, -50 + r * 20, '#bdb3a2'); // paving bands
    fountain(ch, F, 0, 0);
    for (const [lx, lz] of [[-28, -40], [28, -40], [-28, 40], [28, 40], [-28, 0], [28, 0]]) {
      ch.block(F, 3.2, 0.7, 3.2, lx, 0, lz, '#a8a196');
      const p = F.toW(lx, lz);
      ch.solid.push(cylinder(0.22, 0.3, 3.4, 6, p.x, y + 0.7, p.z, '#6b5040'));
      ch.solid.push(paint(new THREE.IcosahedronGeometry(2.3, 0).translate(p.x, y + 5.2, p.z), '#5f8a4a', 0.08));
    }
    for (const [lx, lz, r] of [[-12, -14, 0], [12, -14, 0], [-12, 14, Math.PI], [12, 14, Math.PI]]) {
      const Bf = frame(F.toW(lx, lz).x, F.toW(lx, lz).z, Math.sin(r + F.rot), Math.cos(r + F.rot), y);
      ch.block(Bf, 2.4, 0.45, 0.6, 0, 0, 0, '#8a6446'); ch.box(Bf, 2.4, 0.6, 0.12, 0, 0.45, -0.25, '#8a6446');
      out.benches.push({ x: F.toW(lx, lz).x, z: F.toW(lx, lz).z, yaw: r + F.rot });
    }
    // Food truck (static) with a serving hatch + awning, vendor inside.
    const tr = frame(F.toW(18, 28).x, F.toW(18, 28).z, 1, 0, y);
    ch.block(tr, 5.6, 2.6, 2.3, 0, 0.45, 0, '#e2c25a');
    ch.box(tr, 2.2, 1.1, 0.06, -0.6, 1.4, 1.17, '#2b2b2e');
    ch.box(tr, 2.6, 0.1, 1.1, -0.6, 2.6, 1.7, '#c8322a');
    ch.box(tr, 2.0, 1.2, 2.2, 2.4, 0.45, 0, '#f4f1e8');
    for (const [x, z] of [[-1.9, 1.0], [1.9, 1.0], [-1.9, -1.0], [1.9, -1.0]]) ch.box(tr, 0.6, 0.6, 0.25, x, 0.05, z * 1.1, '#262628');
    townAtlas.sign(tr, townAtlas.row('TACO TRUCK', '#e2c25a', '#c8322a'), 3.2, 0.6, -0.6, 2.95, 1.2);
    const vp = tr.toW(-0.6, 0.3);
    out.npcSpots.push({ role: 'vendor', x: vp.x, y: y + 0.45, z: vp.z, yaw: tr.rot, action: 'look' });
    const cust = tr.toW(-0.6, 2.6);
    out.npcSpots.push({ role: 'office', x: cust.x, y, z: cust.z, yaw: tr.rot + Math.PI, action: 'phone' });
    // Plaza sign + two street billboards.
    townAtlas.sign(frame(cx, bz0 + 1.5, 0, -1, y), townAtlas.row('CITY PLAZA', '#2f3b44', '#f4f1e8'), 8, 1.2, 0, 2.2, 0);
    ch.box(frame(cx, bz0 + 1.5, 0, -1, y), 8.4, 1.6, 0.3, 0, 1.4, -0.2, '#2b2b2e');
    for (const [s, ad] of [[-1, ADS[0]], [1, ADS[3]]]) {
      const Bf = frame(cx + s * 36, bz1 - 3, 0, 1, y);
      ch.box(Bf, 0.35, 5, 0.35, 0, 0, -0.3, '#2b2b2e');
      ch.box(Bf, 9, 3.4, 0.3, 0, 5, -0.4, '#2b2b2e');
      townAtlas.sign(Bf, townAtlas.row(ad[0], ad[1], ad[2]), 8.6, 3.0, 0, 6.7, -0.2);
    }
    out.places.push({ kind: 'park', x: cx, z: cz, label: 'City Plaza' });
    out.landmarks.push({ name: 'City Plaza fountain', x: cx, z: cz });
    // Office workers on the benches.
    out.npcSpots.push({ role: 'office', x: F.toW(-12, -14.6).x, y, z: F.toW(-12, -14.6).z, yaw: F.rot, action: 'bench' });
    out.npcSpots.push({ role: 'office', x: F.toW(12, 14.6).x, y, z: F.toW(12, 14.6).z, yaw: F.rot + Math.PI, action: 'bench' });
  }

  // ---- Bus shelters on Terrace Pde (downtown) ----------------------------------------------------
  for (const [x, side] of [[655, -1], [835, 1], [925, -1]]) {
    const z = Z[1] + side * (T.hw + T.kerb + 2.9);
    const ch = chunk(`d${x < X[4] ? 3 : x < X[5] ? 4 : x < X[6] ? 5 : 6}${side < 0 ? 0 : 1}`);
    const S = frame(x, z, 0, -side, y);
    ch.block(S, 3.6, 0.1, 1.4, 0, 2.4, 0, '#cfd3d6');
    ch.box(S, 3.6, 2.4, 0.06, 0, 0, -0.65, '#9fc4d6', { glassy: true });
    for (const sx of [-1.75, 1.75]) ch.block(S, 0.08, 2.4, 0.08, sx, 0, -0.65, '#5c5f66');
    ch.block(S, 2.4, 0.45, 0.4, 0, 0, -0.35, '#8a6446');
    out.stops.push({ x, z });
  }

  for (const ch of chunks.values()) {
    const c = ch.finish(parent);
    out.chunks.push(c);
    out.colliders.push(...ch.colliders);
    if (ch.props.length) out.propChunks.push(ch);
  }
  const neonMesh = neon.mesh();
  neonMesh.name = 'downtown-neon';
  const ng = new THREE.Group(); ng.name = 'downtown-neon'; ng.add(neonMesh); parent.add(ng);
  out.chunks.push({ group: ng, x: (DOWNTOWN.x0 + DOWNTOWN.x1) / 2, z: Z[1], r: 200 });
  out.neon = neon;
  // Neon glows at night.
  out.updaters.push((dt, ctx) => { const d = ctx.dusk ?? 0; neon.mat.emissiveIntensity = 0.25 + d * 1.6; });
  return out;
}
